class Account {
  owner: string;
  balance: number;

  constructor(owner: string, openingBalance: number) {
    this.owner = owner;
    this.balance = openingBalance;
  }

  deposit(amount: number): void {
    this.balance += amount;
  }
}

const account = new Account("Ada", 100);
account.deposit(50);
console.log(`${account.owner}: ${account.balance}`);

account.deposit("50");

class Timer {
  startedAt: number;

  start(): void {
    this.startedAt = Date.now();
  }
}

class Counter {
  #ticks = 0;

  constructor(private readonly step: number, public label = "counter") {}

  tick(): number {
    this.#ticks += this.step;
    return this.#ticks;
  }
}

const counter = new Counter(2);
console.log(counter.tick(), counter.tick(), counter.label);

console.log(counter.step);

interface Shape {
  area(): number;
}

abstract class BaseShape implements Shape {
  constructor(readonly name: string) {}

  abstract area(): number;

  describe(): string {
    return `${this.name}: ${this.area().toFixed(2)}`;
  }
}

class Circle extends BaseShape {
  constructor(private radius: number) {
    super("circle");
  }

  override area(): number {
    return Math.PI * this.radius ** 2;
  }
}

class Square extends BaseShape {
  constructor(private side: number) {
    super("square");
  }

  override area(): number {
    return this.side ** 2;
  }
}

const shapes: Shape[] = [new Circle(1), new Square(3)];
for (const shape of shapes) {
  console.log(shape.area().toFixed(2));
}
console.log(new Circle(2).describe());
